/*
 * A stand-in for KaTeX's auto-render, so the sheet tests run offline.
 *
 * It does what the build depends on and nothing else: every inline or
 * display formula becomes a .katex span, and a formula using the undefined
 * macro \undefinedmacro becomes a .katex-error span whose title carries the
 * message -- the element and attribute the real renderer produces with
 * throwOnError: false.
 */
window.renderMathInElement = function (root) {
  var html = root.innerHTML;
  var replace = function (match, tex) {
    if (tex.indexOf("\\undefinedmacro") >= 0) {
      return '<span class="katex-error" title="ParseError: KaTeX parse error: Undefined control sequence: \\undefinedmacro">' + tex + "</span>";
    }
    return '<span class="katex">' + tex + "</span>";
  };
  html = html.replace(/\$\$([\s\S]*?)\$\$/g, replace);
  html = html.replace(/\\\(([\s\S]*?)\\\)/g, replace);
  root.innerHTML = html;
};
